window.PRELOADED_CHAPTERS_C10SK = {"1":"<section class=\"chapter-section\" id=\"ch1\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः १</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">पद्यभागः (श्लोकाः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>प्रथमः पाठः — शुचिपर्यावरणम्</h2>\n      <p class=\"ch-author\">रचयिता: प्रो. हरिदत्त शर्मा (गीतिसङ्ग्रहः: लसलल्लतिका)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>महानगरीय प्रदूषणस्य भयानकतां प्रदर्श्य कविः शुद्धप्रकृतिशरणं प्रति गन्तुं प्रेरयति। यत्र शुद्धः वायुः, निर्मलं जलं, शान्तं च वातावरणं स्यात्।</p>\n      <p style=\"margin-top:8px;font-style:italic;color:#6b21a8;\"><strong>विशेष-टिप्पणी:</strong> दुर्ग्रहे संसारे प्रकृतेरेव एकं शरणम्। महानगरस्य कृत्रिमजीवनात् दूरे एकान्ते कान्तारे क्षणमपि भ्रमणं जीवनस्य सौख्यं जनयति।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch1_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch1_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः (Only 1-2 words as per CBSE Marking Rubric)</span>\n      </div>\n      <div class=\"q-text\">अधोलिखितानां प्रश्नानाम् उत्तराणि एकपदेन लिखत:<br>(क) अत्र जीवितं कीदृशं जातम्?<br>(ख) अनिशं महानगरमध्ये किं प्रचलति?<br>(ग) कुत्सितवस्तुमिश्रितं किमस्ति?<br>(घ) अहं कस्मै जीवनं कामये?<br>(ङ) केषां माला रमणीया?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">दुर्वहम्</span> (कठिनम्)</p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">कालायसचक्रम्</span> (लोहचक्रम्)</p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">भक्ष्यम्</span> (भोज्यवस्तु)</p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">मानवाय</span> (मानवस्य कल्याणाय)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">ललितलतानाम् / कुसुमावली</span></p>\n</div>\n<div class=\"hi-trans\">\n  <strong>हिन्दी व्याख्या:</strong> (क) यहाँ जीवन अत्यंत कठिन (दुर्वह) हो गया है। (ख) महानगरों में दिन-रात लोहे का पहिया (कालायसचक्र) चल रहा है। (ग) खाने की सभी वस्तुएं (भक्ष्य) मिलावटी हो चुकी हैं। (घ) कवि मानव के लिए कल्याणकारी जीवन की कामना करता है। (ङ) हरी-भरी सुंदर लताओं की माला रमणीय है।\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) 'दुर्वहम्' शुद्ध पदस्य लेखनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) 'कालायसचक्रम्' शुद्ध पदस्य लेखनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ग) 'भक्ष्यम्' शुद्ध विभक्ति-प्रयोगेण</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(घ) 'मानवाय' चतुर्थी-विभक्तियुक्त-पदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ङ) 'ललितलतानाम्' षष्ठी-बहुवचन-पदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch1_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch1_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-च) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः (Full Sentence with Subject-Verb Concord)</span>\n      </div>\n      <div class=\"q-text\">अधोलिखितानां प्रश्नानाम् उत्तराणि संस्कृतभाषया पूर्णवाक्येन लिखत:<br>(क) कविः किमर्थं प्रकृतेः शरणम् इच्छति?<br>(ख) कस्मात् कारणात् महानगरेषु संसरणं कठिनं वर्तते?<br>(ग) अस्माकं पर्यावरणे किं किं दूषितमस्ति?<br>(घ) कविः कुत्र सञ्चरणं कर्तुम् इच्छति?<br>(ङ) स्वस्थजीवनाय कीदृशे वातावरणे भ्रमणीयम्?<br>(च) अन्तिमे पद्यांशे कवेः का कामना अस्ति?</div>\n      <div class=\"q-marks\">१ × ६ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> अत्र धरातले जीवितं दुर्वहं जातम्, अतः कविः प्रकृतेः शरणम् इच्छति।</p>\n  <p><strong>(ख)</strong> महानगरेषु मार्गेषु यानानां ह्यनन्ताः पङ्क्तयः धावन्ति, अस्मात् कारणात् तत्र संसरणं कठिनं वर्तते।</p>\n  <p><strong>(ग)</strong> अस्माकं पर्यावरणे वायुमण्डलं, जलं, भक्ष्यं, धरातलं च सर्वं कलुषितं दूषितं चास्ति।</p>\n  <p><strong>(घ)</strong> कविः एकान्ते कान्तारे (वने) क्षणमपि सञ्चरणं कर्तुम् इच्छति।</p>\n  <p><strong>(ङ)</strong> स्वस्थजीवनाय खगकुलकलारवपूजिते, प्राकृतिके, प्रदूषणरहिते च वातावरणे भ्रमणीयम्।</p>\n  <p><strong>(च)</strong> अन्तिमे पद्यांशे कवेः कामना अस्ति यत् पाषाणी सभ्यता निसर्गे न समाविष्टा स्यात्, मानवाय च स्वस्थं जीवनं भूयात्।</p>\n</div>\n<div class=\"hi-trans\">\n  <strong>हिन्दी व्याख्या:</strong> कवि प्रदूषण और कोलाहल से दूर प्राकृतिक शांति चाहता है। महानगरों में अनगिनत वाहनों की कतारों के कारण चलना भी दुष्कर है। हमारा जल, वायु और भोजन सब विषाक्त हो चुका है। अतः कवि प्रकृति की गोद में शांति और मानव कल्याण की प्रार्थना करता है।\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् प्रश्ने शुद्ध-वाक्यरचना एवं कर्तृ-क्रिया-अन्वयः</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">यथार्थ-विषयवस्तु-प्रतिपादनम् एवं शुद्ध-वर्तनी</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch1_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch1_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — सन्धिं / सन्धिविच्छेदं कुरुत</span>\n        <span class=\"word-limit-pill\">नियमबद्ध सन्धियुक्त पदम् अथवा विच्छेदः</span>\n      </div>\n      <div class=\"q-text\">सन्धिसन्धिविच्छेदं कुरुत:<br>१. प्रकृतिः + एव = _____<br>२. स्यात् + न + एव = _____<br>३. हि + अनन्ताः = _____<br>४. बहिः + अन्तः + जगति = _____<br>५. अस्मात् + नगरात् = _____<br>६. सम् + चरणम् = _____<br>७. धूमम् + मुञ्चति = _____</div>\n      <div class=\"q-marks\">१/२ × ७ = ३.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>१. प्रकृतिः + एव = <strong>प्रकृतिरेव</strong> (ऋत्व-विसर्गसन्धिः)</p>\n  <p>२. स्यात् + न + एव = <strong>स्यान्नैव</strong> (व्यञ्जनसन्धिः + वृद्धिसन्धिः)</p>\n  <p>३. हि + अनन्ताः = <strong>ह्यनन्ताः</strong> (यण्-स्वरसन्धिः)</p>\n  <p>४. बहिः + अन्तः + जगति = <strong>बहिरन्तर्जगति</strong> (ऋत्व-विसर्गसन्धिः)</p>\n  <p>५. अस्मात् + नगरात् = <strong>अस्मान्नगरात्</strong> (अनुनासिक-व्यञ्जनसन्धिः)</p>\n  <p>६. सम् + चरणम् = <strong>सञ्चरणम्</strong> (परसवर्ण-सन्धिः)</p>\n  <p>७. धूमम् + मुञ्चति = <strong>धूमं मुञ्चति / धूम्मञ्चति</strong> (अनुस्वारसन्धिः)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सन्धिनियमसहितं शुद्धपदलेखनाय प्रतिपदम्</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch1_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch1_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — अव्ययपदानां साहाय्येन रिक्तस्थानपूर्तिः</span>\n        <span class=\"word-limit-pill\">मञ्जूषातः उचितपदचयनम्</span>\n      </div>\n      <div class=\"q-text\">मञ्जूषातः अव्ययपदानि चित्वा रिक्तस्थानानि पूरयत:<br>[मञ्जूषा: भृशम्, यत्र, तत्र, अत्र, अपि, एव, सदा, बहिः]<br>(१) इदानीं वायुमण्डलं _____ प्रदूषितमस्ति।<br>(२) _____ जीवनं दुर्वहम् अस्ति।<br>(३) प्राकृतिक-वातावरणे क्षणमपि सञ्चरणं _____ लाभदायकं भवति।<br>(४) पर्यावरणस्य संरक्षणम् _____ प्रकृतेः आराधना।<br>(५) _____ समयस्य सदुपयोगः करणीयः।<br>(६) भूकम्पसमये गृहात् _____ गमनमेव समीचीनं भवति।</div>\n      <div class=\"q-marks\">१/२ × ६ = ३ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(१) इदानीं वायुमण्डलं <strong>भृशम्</strong> प्रदूषितमस्ति।</p>\n  <p>(२) <strong>अत्र</strong> जीवनं दुर्वहम् अस्ति।</p>\n  <p>(३) प्राकृतिक-वातावरणे क्षणमपि सञ्चरणं <strong>अपि</strong> लाभदायकं भवति।</p>\n  <p>(४) पर्यावरणस्य संरक्षणम् <strong>एव</strong> प्रकृतेः आराधना।</p>\n  <p>(५) <strong>सदा</strong> समयस्य सदुपयोगः करणीयः।</p>\n  <p>(६) भूकम्पसमये गृहात् <strong>बहिः</strong> गमनमेव समीचीनं भवति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उचित-अव्ययपद-चयनार्थं प्रतिरिक्तस्थानम्</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch1_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch1_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — पर्यायपदानि एवं विलोमपदानि लिखत</span>\n        <span class=\"word-limit-pill\">सटीक संस्कृत पदानि</span>\n      </div>\n      <div class=\"q-text\">अधोलिखितपदानां पर्यायपदानि विलोमपदानि च लिखत:<br><strong>पर्यायपदानि:</strong> सलिलम्, आम्रम्, वनम्, शरीरम्, कुटिलम्, पाषाणः<br><strong>विलोमपदानि:</strong> सुकरम्, दूषितम्, दानवाय, सान्तम्</div>\n      <div class=\"q-marks\">१/२ × ८ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>पर्यायपदानि (Synonyms):</strong></p>\n  <ul>\n    <li>सलिलम् = <strong>जलम् / तोयम् / वारि</strong></li>\n    <li>आम्रम् = <strong>रसालम्</strong></li>\n    <li>वनम् = <strong>कान्तारम् / विपिनम्</strong></li>\n    <li>शरीरम् = <strong>तनुः / देहः / कायः</strong></li>\n    <li>कुटिलम् = <strong>वक्रम्</strong></li>\n    <li>पाषाणः = <strong>प्रस्तरः</strong></li>\n  </ul>\n  <p style=\"margin-top:10px;\"><strong>विलोमपदानि (Antonyms):</strong></p>\n  <ul>\n    <li>सुकरम् × <strong>दुर्वहम्</strong></li>\n    <li>दूषितम् × <strong>शुचि / शुद्धम्</strong></li>\n    <li>दानवाय × <strong>मानवाय</strong></li>\n    <li>सान्तम् × <strong>अनन्तम्</strong></li>\n  </ul>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-पर्यायपद-विलोमपद-लेखनाय प्रतिपदम्</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch1_q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch1_q6')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ६ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">पूर्णवाक्येन प्रश्नवाचक-चिह्नयुक्त (?) वाक्यरचना</span>\n      </div>\n      <div class=\"q-text\">रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणं कुरुत:<br>(क) शकटीयानं <u>कज्जलमलिनं</u> धूमं मुञ्चति।<br>(ख) उद्याने <u>पक्षिणां</u> कलरवं चेतः प्रसादयति।<br>(ग) पाषाणीसभ्यतायां <u>लतातरुगुल्माः</u> प्रस्तरतले पिष्टाः सन्ति।<br>(घ) महानगरेषु <u>वाहनानाम्</u> अनन्ताः पङ्क्तयः धावन्ति।<br>(ङ) प्रकृत्याः <u>सन्निधौ</u> वास्तविकं सुखं विद्यते।</div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> शकटीयानं <strong>कीदृशं</strong> धूमं मुञ्चति?</p>\n  <p><strong>(ख)</strong> उद्याने <strong>केषाम्</strong> कलरवं चेतः प्रसादयति?</p>\n  <p><strong>(ग)</strong> पाषाणीसभ्यतायां <strong>के</strong> प्रस्तरतले पिष्टाः सन्ति?</p>\n  <p><strong>(घ)</strong> महानगरेषु <strong>केषाम्</strong> अनन्ताः पङ्क्तयः धावन्ति?</p>\n  <p><strong>(ङ)</strong> प्रकृत्याः <strong>कस्याम् / कुत्र</strong> वास्तविकं सुखं विद्यते?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उचित-किम्-रूपस्य अथवा प्रश्नवाचक-अव्ययस्य प्रयोगः</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्ये प्रश्नचिह्नयुक्त (?) वाक्यलेखनम्</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch1_q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch1_q7')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ७ — अधोलिखितस्य श्लोकस्य अन्वयं पूरयत</span>\n        <span class=\"word-limit-pill\">मञ्जूषातः पदानि चित्वा रिक्तस्थानपूर्तिः</span>\n      </div>\n      <div class=\"q-text\">श्लोकस्य अन्वयं पूरयत:<br><em>'कज्जलमलिनं धूमं मुञ्चति शतशकटीयानम्। वाष्पयानमाला संधावति वितरन्ती ध्वानम्॥'</em><br>अन्वयः: शतशकटीयानम् (१) _____ धूमं मुञ्चति। ध्वानं (२) _____ वाष्पयानमाला (३) _____। यानानाम् अनन्ताः (४) _____, अतः संसरणं कठिनम्।</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>अन्वयः: शतशकटीयानम् <strong>(१) कज्जलमलिनं</strong> धूमं मुञ्चति। ध्वानं <strong>(२) वितरन्ती</strong> वाष्पयानमाला <strong>(३) संधावति</strong>। यानानाम् अनन्ताः <strong>(४) पङ्क्तयः</strong>, अतः संसरणं कठिनम्।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-रिक्तस्थाने</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #7c3aed;\">\n        <div class=\"cbq-type\" style=\"color:#7c3aed;\">योग्यता-आधारितः प्रश्नः (NEP 2020 Competency Question)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> 'शुचिपर्यावरणम्' इति पाठस्य आधारेण स्पष्टीकुरुत यत् वर्तमानकाले औद्योगिकीकरणं कथं मानवस्वास्थ्यस्य कृते विपत्तिजनकं वर्तते? (शब्द-सीमा: ३०-४० शब्दाः | अंकाः: २)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>वर्तमानकाले महानगरेषु यन्त्रोद्योगानां वाहनानां च आधिक्येन वायुमण्डलं कज्जलमलिनेन धूमेन कलुषितं जातम्। नद्यः विषाक्तजलेन दूषिताः अभवन्। एतेन मानवाः श्वास-हृद्रोगादिभिः पीडिताः सन्ति। अतः जीवनरक्षायै प्रकृतिसंरक्षणं शुद्धपर्यावरणं चात्यन्तमत्यावश्यकम्।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <div></div>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">अग्रिमः पाठः (Ch 2) →</button>\n  </div>\n</section>","2":"<section class=\"chapter-section\" id=\"ch2\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः २</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">गद्यभागः (कथा) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>द्वितीयः पाठः — बुद्धिर्बलवती सदा</h2>\n      <p class=\"ch-author\">कथासङ्ग्रहः: शुकसप्ततिः (नीतिकथा)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>आपत्काले बुद्धिचातुर्येण एव संकटमुक्तिः भवति। बुद्धिमती नाम स्त्री स्वबुद्धिबलेन व्याघ्रं शृगालं च वञ्चयित्वा स्वपुत्रयोः रक्षां करोति।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch2_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch2_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">अधोलिखितानां प्रश्नानाम् उत्तराणि एकपदेन लिखत:<br>(क) बुद्धिमती कुत्र व्याघ्रं ददर्श?<br>(ख) भामिनी कया विमुक्ता?<br>(ग) सर्वदा सर्वकार्येषु का बलवती?<br>(घ) व्याघ्रः कस्मात् बिभेति?<br>(ङ) प्रत्युत्पन्नमतिः बुद्धिमती कं आक्षिपन्ती उवाच?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">गहनकानने</span> (घने वने)</p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">निजबुद्ध्या</span> (स्वबुद्ध्या)</p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">बुद्धिः</span></p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">मानुषात्</span></p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">जम्बुकम्</span> (शृगालम्)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदोत्तराय शुद्धविभक्तियुक्ताय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch2_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch2_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">अधोलिखितानां प्रश्नानाम् उत्तराणि संस्कृतभाषया पूर्णवाक्येन लिखत:<br>(क) बुद्धिमती केन उपेता पितुर्गृहं प्रति चलिता?<br>(ख) व्याघ्रः किं विचार्य पलायितः?<br>(ग) लोके महतो भयात् कः मुच्यते?<br>(घ) जम्बुकः किं वदन् व्याघ्रस्य उपहासं करोति?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> बुद्धिमती पुत्रद्वयोपेता (स्वपुत्रद्वयेन सह) पितुर्गृहं प्रति चलिता।</p>\n  <p><strong>(ख)</strong> 'इयं काचित् व्याघ्रमारी' इति विचार्य व्याघ्रः भयाकुलचित्तो नष्टः (पलायितः)।</p>\n  <p><strong>(ग)</strong> लोके बुद्धिमान् जनः निजबुद्ध्या महतो भयात् मुच्यते।</p>\n  <p><strong>(घ)</strong> जम्बुकः अवदत् यत् 'यत् त्वया मानुषादपि भयं दर्शितम्, महदाश्चर्यमेतत्' इति वदन् स व्याघ्रस्य उपहासं करोति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्ये शुद्ध-वाक्यविन्यासः एवं तथ्यप्रतिपादनम्</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch2_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch2_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नवाचक-चिह्नयुक्त पूर्णवाक्यम्</span>\n      </div>\n      <div class=\"q-text\">प्रश्ननिर्माणं कुरुत:<br>(क) तत्र राजसिंहो नाम <u>राजपुत्रः</u> वसति स्म।<br>(ख) बुद्धिमती चपेटया <u>पुत्रौ</u> प्रहृतवती।<br>(ग) व्याघ्रं दृष्ट्वा धूर्तः <u>शृगालः</u> अवदत्।<br>(घ) त्वं <u>मानुषात्</u> बिभेषि।<br>(ङ) पुरा त्वया <u>मह्यम्</u> व्याघ्रत्रयं दत्तम्।</div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> तत्र राजसिंहो नाम <strong>कः</strong> वसति स्म?</p>\n  <p><strong>(ख)</strong> बुद्धिमती चपेटया <strong>कौ</strong> प्रहृतवती?</p>\n  <p><strong>(ग)</strong> व्याघ्रं दृष्ट्वा धूर्तः <strong>कः</strong> अवदत्?</p>\n  <p><strong>(घ)</strong> त्वं <strong>कस्मात्</strong> बिभेषि?</p>\n  <p><strong>(ङ)</strong> पुरा त्वया <strong>कस्मै</strong> व्याघ्रत्रयं दत्तम्?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विभक्ति-वचनानुसारं शुद्ध-किम्-रूपम् + प्रश्नचिह्नम् (?)</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch2_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch2_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — घटनाक्रमानुसारेण वाक्यानि लिखत</span>\n        <span class=\"word-limit-pill\">कथायाः कालक्रमानुसारं क्रमबद्धता</span>\n      </div>\n      <div class=\"q-text\">कथायाः घटनाक्रमानुसारेण वाक्यानि पुनः लिखत:<br>१. व्याघ्रः व्याघ्रमारी इयमिति मत्वा पलायितः।<br>२. बुद्धिमती पुत्रद्वयेन सह पितुर्गृहं प्रति चलिता।<br>३. जम्बुककृतोत्साहः व्याघ्रः पुनः काननम् आगच्छत्।<br>४. मार्गे सा एकं व्याघ्रम् अपश्यत्।<br>५. प्रत्युत्पन्नमतिः सा शृगालम् आक्षिपन्ती उवाच।<br>६. गलगालबद्धशृगालकः व्याघ्रः पुनः पलायितः।<br>७. व्याघ्रं दृष्ट्वा सा पुत्रौ ताडयन्ती उवाच - अधुना एकमेव व्याघ्रं विभज्य भुङ्क्ताम्।<br>८. बुद्धिमती निजबुद्ध्या व्याघ्रस्य भयात् मुक्ता अभवत्।</div>\n      <div class=\"q-marks\">४ अंकाः (१/२ × ८)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>शुद्धः घटनाक्रमः:</strong></p>\n  <ol style=\"margin-left:20px; line-height:1.8;\">\n    <li>(२) बुद्धिमती पुत्रद्वयेन सह पितुर्गृहं प्रति चलिता।</li>\n    <li>(४) मार्गे सा एकं व्याघ्रम् अपश्यत्।</li>\n    <li>(७) व्याघ्रं दृष्ट्वा सा पुत्रौ ताडयन्ती उवाच - अधुना एकमेव व्याघ्रं विभज्य भुङ्क्ताम्।</li>\n    <li>(१) व्याघ्रः 'व्याघ्रमारी इयम्' इति मत्वा भयाकुलः पलायितः।</li>\n    <li>(३) जम्बुककृतोत्साहः व्याघ्रः पुनः काननम् आगच्छत्।</li>\n    <li>(५) प्रत्युत्पन्नमतिः सा शृगालम् आक्षिपन्ती उवाच।</li>\n    <li>(६) गलगालबद्धशृगालकः व्याघ्रः पुनः पलायितः।</li>\n    <li>(८) बुद्धिमती निजबुद्ध्या व्याघ्रस्य भयात् मुक्ता अभवत्।</li>\n  </ol>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्य वाक्यस्य यथार्थक्रमस्थापनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch2_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch2_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — सन्धि-समास-प्रकृतिप्रत्ययाः</span>\n        <span class=\"word-limit-pill\">निर्देशानुसारम्</span>\n      </div>\n      <div class=\"q-text\">(क) पितुर्गृहम् = _____ + _____<br>(ख) एकैकशः = _____ + _____<br>(ग) भयेन आकुलः = _____ (समस्तपदम्)<br>(घ) हन् + क्त = _____, दृश् + क्त्वा = _____<br>(ङ) 'शीघ्रम्' इत्यर्थे पाठे किं पदं प्रयुक्तम्?</div>\n      <div class=\"q-marks\">३ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) पितुर्गृहम् = <strong>पितुः + गृहम्</strong> (ऋत्व-विसर्गसन्धिः)</p>\n  <p>(ख) एकैकशः = <strong>एक + एकशः</strong> (वृद्धिसन्धिः)</p>\n  <p>(ग) भयेन आकुलः = <strong>भयाकुलः</strong> (तृतीया तत्पुरुष समासः)</p>\n  <p>(घ) हन् + क्त = <strong>हतः</strong>; दृश् + क्त्वा = <strong>दृष्ट्वा</strong></p>\n  <p>(ङ) 'शीघ्रम्' इत्यर्थे <strong>तूर्णम् / सत्वरम्</strong> इति पदं प्रयुक्तम्।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् व्याकरणभागे शुद्धोत्तराय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #d97706;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक-प्रश्नः (Value Based Competency)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> 'बुद्धिर्बलवती सदा' इति पाठेन किं शिक्षणं प्राप्यते? जीवने संकटसमये बुद्धेः कीदृशं महत्त्वं वर्तते? (शब्द-सीमा: ३०-५० शब्दाः | अंकाः: २)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>अनेन पाठेन ज्ञायते यत् शारीरिकबलात् बुद्धिबलं श्रेष्ठतरं भवति। संकटकाले धैर्यं न त्यक्तव्यम्। यदा बुद्धिमती स्वबुद्ध्या महाभयंकरं व्याघ्रमपि पराजितवती, तदा स्पष्टं भवति यत् प्रत्युत्पन्नमतिः मानवः बुद्धिकौशलेन विषमपरिस्थितौ अपि विजयं प्राप्नोति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(1)\">← पूर्वतनः पाठः (Ch 1)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">अग्रिमः पाठः (Ch 3) →</button>\n  </div>\n</section>","3":"<section class=\"chapter-section\" id=\"ch3\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ३</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">पद्यभागः (आयुर्वेदश्लोकाः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>तृतीयः पाठः — व्यायामः सर्वदा पथ्यः</h2>\n      <p class=\"ch-author\">मूलग्रन्थः: सुश्रुतसंहिता (चिकित्सास्थानम्)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>शारीरिकस्वास्थ्यस्य कृते नियमितव्यायामस्य महत्त्वम्। व्यायामेन देहोपचयः, कान्तिः, आरोग्यं, पाचनशक्तिः च सिध्यति।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch3_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch3_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) परमं आरोग्यं कस्मात् उपजायते?<br>(ख) कस्य मांसं स्थिरीभवति?<br>(ग) कः सर्वदा पथ्यः?<br>(घ) कैः पुम्भिः सर्वर्तुषु व्यायामः कर्तव्यः?<br>(ङ) अर्धबलस्य लक्षणं किम्?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">व्यायामात्</span></p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">व्यायामाभिरतस्य</span> (व्यायामशीलात् जनस्य)</p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">व्यायामः</span></p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">आत्महितैषिभिः</span> (सर्वैः पुरुषैः)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">हृदिस्थानस्थितो वायुः वक्त्रं प्रपद्यते</span> (यदा मुखे श्वासः आयाति)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-पदलेखनाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch3_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch3_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-ङ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) कीदृशं कर्म व्यायामसंज्ञितम् कथ्यते?<br>(ख) व्यायामात् किं किं उपजायते?<br>(ग) जरा कस्य सकाशं सहसा न समधिरोहति?<br>(घ) कस्य विरुद्धमपि भोजनं परिपच्यते?<br>(ङ) कियान् बलेन व्यायामः कर्तव्यः?</div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> शरीरप्रयासजननं (शरीरेण यः आयासः जन्यते तत्) कर्म व्यायामसंज्ञितं कथ्यते।</p>\n  <p><strong>(ख)</strong> व्यायामात् श्रमकॢमपिपासा-उष्ण-शीतादीनां सहिष्णुता, आरोग्यं च उपजायते।</p>\n  <p><strong>(ग)</strong> व्यायामं कुर्वतः जनस्य सकाशं जरा (वार्धक्यम्) सहसा न समधिरोहति।</p>\n  <p><strong>(घ)</strong> नित्यं व्यायामं कुर्वतः जनस्य विदग्धमविदग्धं वा विरुद्धमपि भोजनं निर्दोषं परिपच्यते।</p>\n  <p><strong>(ङ)</strong> सर्वर्तुषु आत्महितैषिभिः पुरुषैः बलेनार्धेन (अर्धबलेन) व्यायामः कर्तव्यः।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वाक्यसंरचना एवं भावशुद्धिः</span><span class=\"marking-marks\">१ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch3_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch3_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — श्लोकान्वयः एवं भावार्थः</span>\n        <span class=\"word-limit-pill\">श्लोकस्य गद्यरूपान्वयः</span>\n      </div>\n      <div class=\"q-text\"><em>'न चास्ति सदृशं तेन किञ्चित् स्थौल्यापकर्षणम्। न च व्यायामिनं मर्त्यमर्दयन्त्यरयो बलात्॥'</em><br>अस्य श्लोकस्य अन्वयं भावार्थं च लिखत।</div>\n      <div class=\"q-marks\">३ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>अन्वयः:</strong> तेन (व्यायामेन) सदृशं स्थौल्यापकर्षणं किञ्चित् न अस्ति। व्यायामिनं मर्त्यम् अरयः बलात् न अर्दयन्ति।</p>\n  <p><strong>भावार्थः:</strong> व्यायामेन स्थूलतायाः (मोटापेस्य) निवारणं भवति। यथा व्यायामी पुरुषः बलवान् भवति, तथैव शत्रवः अथवा रोगाः तं सहसा पीडयितुं न शक्नुवन्ति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-अन्वयलेखनाय</span><span class=\"marking-marks\">१.५ अंकाः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्पष्ट-भावार्थाय</span><span class=\"marking-marks\">१.५ अंकाः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch3_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch3_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नवाचक-वाक्यरचना</span>\n      </div>\n      <div class=\"q-text\">प्रश्ननिर्माणं कुरुत:<br>(क) <u>शरीरायासजननं</u> कर्म व्यायामसंज्ञितम्।<br>(ख) <u>अरयः</u> व्यायामिनं न अर्दयन्ति।<br>(ग) <u>आत्महितैषिभिः</u> व्यायामः कर्तव्यः।<br>(घ) <u>व्यायामतः</u> आरोग्यं लभ्यते।</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <strong>कीदृशं</strong> कर्म व्यायामसंज्ञितम्?</p>\n  <p><strong>(ख)</strong> <strong>के</strong> व्यायामिनं न अर्दयन्ति?</p>\n  <p><strong>(ग)</strong> <strong>कैः</strong> व्यायामः कर्तव्यः?</p>\n  <p><strong>(घ)</strong> <strong>कस्मात्</strong> आरोग्यं लभ्यते?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-प्रश्नवाचकपदम् + (?) चिह्नम्</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch3_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch3_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — तृतीयाविभक्तिप्रयोगेण रिक्तस्थानपूर्तिः</span>\n        <span class=\"word-limit-pill\">तृतीयाविभक्तेः शुद्धरूपम्</span>\n      </div>\n      <div class=\"q-text\">कोष्ठकगतेषु पदेषु तृतीयाविभक्तिं प्रयुज्य रिक्तस्थानानि पूरयत:<br>(क) सः _____ सह भ्रमति। (व्यायाम)<br>(ख) _____ विना जीवनं न सिध्यति। (विद्या)<br>(ग) खञ्जः _____ चलति। (पाद)<br>(घ) सूपकारः _____ भोजनं पचति। (अग्नि)<br>(ङ) बालकः _____ सङ्गीतं शृणोति। (कर्ण)</div>\n      <div class=\"q-marks\">२.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) सः <strong>व्यायामेन</strong> सह भ्रमति।</p>\n  <p>(ख) <strong>विद्यया</strong> विना जीवनं न सिध्यति।</p>\n  <p>(ग) खञ्जः <strong>पादेन</strong> चलति।</p>\n  <p>(घ) सूपकारः <strong>अग्निना</strong> भोजनं पचति।</p>\n  <p>(ङ) बालकः <strong>कर्णाभ्याम् / कर्णेन</strong> सङ्गीतं शृणोति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तृतीयाविभक्तेः शुद्धरूपाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिरिक्तस्थानम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #059669;\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">स्वास्थ्य-विज्ञान-दक्षता (NEP 2020 Health Awareness)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> 'सुश्रुतसंहिता' अनुसारं कति प्रमाणेन व्यायामः विधेयः तथा च अतिव्यायामेन का हानिः सम्भवति? (शब्द-सीमा: २५-३५ शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>आयुर्वेदानुसारं जनैः अर्धबलेन एव व्यायामः कर्तव्यः। यदा हृदिस्थितो वायुः मुखं प्राप्नोति तदा अर्धबलं ज्ञेयम्। सामर्थ्याधिकव्यायामेन क्षयः, कासः, ज्वरः, भ्रमः च रोगाः उद्भवन्ति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(2)\">← पूर्वतनः पाठः (Ch 2)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">अग्रिमः पाठः (Ch 4) →</button>\n  </div>\n</section>","4":"<section class=\"chapter-section\" id=\"ch4\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ४</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">नाटकम् (संवादः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>चतुर्थः पाठः — शिशुलालनम्</h2>\n      <p class=\"ch-author\">मूलनाटकम्: कुन्दमाला (रचयिता: महाकवि-दिङ्नागः)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>श्रीरामस्य सभायां लवकुशयोः आगमनम्, श्रीरामस्य वात्सल्यभावः, पितृपुत्रयोः स्नेहमयः संवादः च।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch4_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch4_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) कुशलवौ कं उपसृत्य प्रणमतः?<br>(ख) तपोवनवासिनः कुशस्य मातरं केन नाम्ना आह्वयन्ति?<br>(ग) वयोऽनुरोधात् कः लालनीयः भवति?<br>(घ) केन सम्बन्धेन वाल्मीकिः लवकुशयोः गुरुः?<br>(ङ) कुत्र लवकुशयोः पितुः नाम न व्यवह्रियते?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">रामम्</span></p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">देव्या</span></p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">शिशुजनः</span> (बालकः)</p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">उपनयनोपदेशेन</span></p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">तपोवने</span></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदोत्तराय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch4_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch4_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) रामाय कुशलवयोः कण्ठाश्लेषस्य स्पर्शः कीदृशः आसीत्?<br>(ख) रामः कुशलवौ कुत्र उपवेशयितुं कथयति?<br>(ग) बालभावात् हिमकरः कुत्र विराजते?<br>(घ) कुशलवयोः वंशस्य कर्ता कः?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> रामाय कुशलवयोः कण्ठाश्लेषस्य स्पर्शः हृदयग्राही हिमकर इव आनन्ददायकः शीतलश्चासीत्।</p>\n  <p><strong>(ख)</strong> रामः कुशलवौ स्वसिंहासनस्य अर्धे (सिंहासनार्धम्) उपवेशयितुं कथयति।</p>\n  <p><strong>(ग)</strong> बालभावात् हिमकरः (चन्द्रमा) पशुपतिमस्तककेतकच्छदत्वं (शिवस्य मस्तकम्) विराजते।</p>\n  <p><strong>(घ)</strong> कुशलवयोः वंशस्य कर्ता सहस्रदीधितिः (भगवान् सूर्यः) अस्ति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्यसंरचना एवं तथ्यशुद्धिः</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch4_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch4_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — रेखाङ्कितपदेषु प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नचिह्नयुक्त पूर्णवाक्यम्</span>\n      </div>\n      <div class=\"q-text\">(क) कुशः <u>रामाय</u> प्रणामं करोति।<br>(ख) तौ <u>सौन्दर्यावलोकजवितेन</u> कौतूहलेन पृच्छतः।<br>(ग) वाल्मीकिः <u>उपनयनोपदेशेन</u> तयोः गुरुः।<br>(घ) <u>हिमकरः</u> पशुपतेः मस्तके विराजते।</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> कुशः <strong>कस्मै</strong> प्रणामं करोति?</p>\n  <p><strong>(ख)</strong> तौ <strong>केन</strong> कौतूहलेन पृच्छतः?</p>\n  <p><strong>(ग)</strong> वाल्मीकिः <strong>केन सम्बन्धेन</strong> तयोः गुरुः?</p>\n  <p><strong>(घ)</strong> <strong>कः</strong> पशुपतेः मस्तके विराजते?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-प्रश्नवाचकपदाय + (?) चिह्नम्</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch4_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch4_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — कः कं प्रति कथयति?</span>\n        <span class=\"word-limit-pill\">वक्ता श्रोता च</span>\n      </div>\n      <div class=\"q-text\">अधोलिखितवाक्येषु कः कं प्रति कथयति?<br>(क) 'आर्यस्य वन्दनायां लव इत्यात्मानं श्रावयामि।'<br>(ख) 'अहो उदात्तरम्यः समुदाचारः। किमभिधानो भवतोर्गुरुः?'<br>(ग) 'जानामहं तस्य नामधेयम् - निरनुक्रोशो नाम।'<br>(घ) 'एवमहमपि चरितार्थोऽस्मि।'</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> वक्ता: <strong>लवः</strong> | श्रोता: <strong>रामं प्रति</strong></p>\n  <p><strong>(ख)</strong> वक्ता: <strong>रामः</strong> | श्रोता: <strong>लवकुशौ प्रति</strong></p>\n  <p><strong>(ग)</strong> वक्ता: <strong>कुशः</strong> | श्रोता: <strong>रामं प्रति</strong></p>\n  <p><strong>(घ)</strong> वक्ता: <strong>रामः</strong> | श्रोता: <strong>विदूषकं/लवकुशौ प्रति</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वक्तुः श्रोतुश्च शुद्धनाम्ने (प्रथमा-द्वितीया विभक्तिभ्याम्)</span><span class=\"marking-marks\">१ अंकः प्रतिवाक्यम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch4_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch4_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — पर्यायपदानि लिखत</span>\n        <span class=\"word-limit-pill\">संस्कृत पर्यायपदानि</span>\n      </div>\n      <div class=\"q-text\">पाठात् चित्वा पर्यायपदानि लिखत:<br>(क) हिमकरः = _____<br>(ख) सम्प्रति = _____<br>(ग) समुदाचारः = _____<br>(घ) पशुपतिः = _____</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) हिमकरः = <strong>शशी / चन्द्रमा / निशाकरः</strong></p>\n  <p>(ख) सम्प्रति = <strong>इदानीम् / अधुना</strong></p>\n  <p>(ग) समुदाचारः = <strong>शिष्टाचारः / सदाचारः</strong></p>\n  <p>(घ) पशुपतिः = <strong>शिवः / शङ्करः / त्रिलोचनः</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-पर्यायपदलेखनाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #2563eb;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">नाट्य-संवेदना-बोधः (Dramaturgy & Ethics)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> श्रीरामस्य लवकुशयोश्च सम्वादे भारतीयसंस्कृतेः कः उदात्तः आदर्शः प्रतिफलितः भवति? (शब्द-सीमा: ३०-४० शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>अत्र बालकानां विनयशीलता, पितरं प्रति आदरभावः, गुरोः महत्ता तथा च श्रीरामस्य अपूर्वं वात्सल्यं सौजन्यं च दृश्यते। सिंहासनस्थः राजा अपि तपस्वीबालकानां कृते सिंहासनार्धं ददाति, एषः भारतीयसदाचारस्य पराकाष्ठा अस्ति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(3)\">← पूर्वतनः पाठः (Ch 3)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\">अग्रिमः पाठः (Ch 5) →</button>\n  </div>\n</section>","5":"<section class=\"chapter-section\" id=\"ch5\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ५</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">गद्यभागः (कथा) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>पञ्चमः पाठः — जननी तुल्यवत्सला</h2>\n      <p class=\"ch-author\">मूलग्रन्थः: महाभारतम् (वनपर्व)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>मातुः स्नेहे सर्वे पुत्राः समानाः भवन्ति, किन्तु दुर्बले अपत्ये मातुः कृपा सहजतया अभ्यधिका भवति। सुरभेः विलापेन इन्द्रस्य हृदयपरिवर्तनम्।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch5_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch5_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) वृषभः कुत्र पपात?<br>(ख) दुर्बले सुते कस्याः अधिका कृपा भवति?<br>(ग) कयोः एकः शरीरेण दुर्बलः आसीत्?<br>(घ) सुरभिः कामवस्थाम् दृष्ट्वा अश्रूणि अमुञ्चत्?<br>(ङ) सर्वपत्येषु कस्याः तुल्यवत्सला?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">क्षेत्रे</span> (भूमौ)</p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">मातुः / सुरभेः</span></p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">बलीवर्दयोः</span> (वृषभयोः)</p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">पुत्रस्य दैन्यम्</span></p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">माता / जननी</span></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-विभक्तियुक्त-एकपदाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch5_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch5_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) कृषकः किं करोति स्म?<br>(ख) माता सुरभिः किमर्थम् अश्रूणि मुञ्चति स्म?<br>(ग) सुरभिः इन्द्रस्य प्रश्नस्य किमुत्तरं ददाति?<br>(घ) इन्द्रः दुर्बलवृषभस्य कष्टम् अपाकर्तुं किं कृतवान्?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> कृषकः बलीवर्दाभ्यां (द्वयोः वृषभयोः साहाय्येन) क्षेत्रकर्षणं करोति स्म।</p>\n  <p><strong>(ख)</strong> भूमौ पतिते स्वपुत्रं दुर्बलं वृषभं दृष्ट्वा माता सुरभिः अश्रूणि मुञ्चति स्म।</p>\n  <p><strong>(ग)</strong> सुरभिः इन्द्राय अवदत् यत् 'हे वासव! अहं पुत्रस्य दैन्यं दृष्ट्वा रोदिमि, दुर्बले सुते मातुः अभ्यधिका कृपा भवति'।</p>\n  <p><strong>(घ)</strong> इन्द्रः मुसलाधारेण प्रवर्षेण (मेघवृष्ट्या) सर्वत्र जलोप्लवं कृत्वा कृषकस्य कर्षणकार्यं स्थगयित्वा वृषभस्य कष्टम् अपाकरोत्।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-पूर्णवाक्यरचनायै</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch5_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch5_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — विशेषण-विशेष्य मेलनम्</span>\n        <span class=\"word-limit-pill\">उचित-सम्बन्धः</span>\n      </div>\n      <div class=\"q-text\">विशेषण-विशेष्यपदानां मेलनं कुरुत:<br>१. दुर्बलम् -> (क) अश्रूणि<br>२. दीने -> (ख) वृषभम्<br>३. मुसलाधारेण -> (ग) सुते<br>४. प्रवृष्ट्या -> (घ) वर्षणेन</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>१. दुर्बलम् = <strong>वृषभम्</strong></p>\n  <p>२. दीने = <strong>सुते</strong></p>\n  <p>३. मुसलाधारेण = <strong>वर्षणेन</strong></p>\n  <p>४. महत्या = <strong>प्रवृष्ट्या</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिमेलनं शुद्धत्वाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch5_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch5_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — रेखाङ्कितपदमाधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नवाचक-वाक्यम्</span>\n      </div>\n      <div class=\"q-text\">(क) सः <u>कृच्छ्रेण</u> भारम् उद्वहति।<br>(ख) <u>सुराधिपः</u> तां अपृच्छत्।<br>(ग) अयं अन्येभ्यो <u>दुर्बलः</u>।<br>(घ) <u>धेनूनाम्</u> माता सुरभिः आसीत्।</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> सः <strong>कथम्</strong> भारम् उद्वहति?</p>\n  <p><strong>(ख)</strong> <strong>कः</strong> तां अपृच्छत्?</p>\n  <p><strong>(ग)</strong> अयं अन्येभ्यो <strong>कीदृशः</strong>?</p>\n  <p><strong>(घ)</strong> <strong>कासाम्</strong> माता सुरभिः आसीत्?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-प्रश्नवाचकपदम् + (?)</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #ea580c;\">\n        <div class=\"cbq-type\" style=\"color:#ea580c;\">मानवीय-संवेदना-परीक्षणम् (NEP 2020 Empathy)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> 'जननी तुल्यवत्सला' इति पाठस्य आधारेण समाजस्य दुर्बलवर्गाणां कृते किं सन्देशः प्रदीयते? (शब्द-सीमा: ३५-४५ शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>यथा माता सर्वपुत्रेषु समाने स्नेहे अपि दुर्बलपुत्रे विशेषकृपां दर्शयति, तथैव समाजे सर्वकारेण श्रेष्ठजनैश्च निर्धनानां दुर्बलानां च रक्षणाय विशेषा साहाय्यता कर्तव्या। दुर्बलसहानुभूतिः एव समाजस्य स्थैर्यस्य आधारः अस्ति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(4)\">← पूर्वतनः पाठः (Ch 4)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\">अग्रिमः पाठः (Ch 6) →</button>\n  </div>\n</section>","6":"<section class=\"chapter-section\" id=\"ch6\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ६</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">पद्यभागः (नीतिश्लोकाः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>षष्ठः पाठः — सुभाषितानि</h2>\n      <p class=\"ch-author\">सङ्ग्रहः: भर्तृहरि-नीतिशतकम् एवं पञ्चतन्त्रम्</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>मानवजीवने परिश्रमस्य, ज्ञानस्य, धैर्यस्य, क्रोधत्यागस्य च अपरिहार्यता। नीतिश्लोकानां माध्यमेन सदाचारस्य बोधः।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch6_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch6_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) मनुष्याणां शरीरस्थो महान् रिपुः कः?<br>(ख) गुणी किं वेत्ति?<br>(ग) केषां सम्पत्तौ च विपत्तौ च महतामेकरूपता?<br>(घ) पशूनापि कीदृशः अर्थः गृह्यते?<br>(ङ) उदयसमये रक्तः अस्तसमये च कः रक्तः भवति?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">आलस्यम्</span></p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">गुणम्</span></p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">महताम्</span> (सत्पुरुषाणाम्)</p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">उदीरितः</span> (कथितः अर्थः)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">सविता</span> (सूर्यः)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदोत्तराय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch6_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch6_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) केन समः बन्धुः नास्ति?<br>(ख) वसन्तस्य गुणं कः जानाति?<br>(ग) बुद्धयः कीदृश्यः भवन्ति?<br>(घ) नराणां प्रथमः शत्रुः कः?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> उद्यमेन (परिश्रमेन) समः कोऽपि बन्धुः नास्ति।</p>\n  <p><strong>(ख)</strong> वसन्तस्य गुणं पिकः (कोकिलः) जानाति, न तु वायसः (काकः)।</p>\n  <p><strong>(ग)</strong> बुद्धयः परेङ्गितज्ञानफलाः (परेषाम् इङ्गितैरेव भावं जानन्त्यः) भवन्ति।</p>\n  <p><strong>(घ)</strong> नराणां देहविनाशाय प्रथमः शत्रुः शरीरस्थः क्रोधः अस्ति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्ये शुद्ध-कर्तृ-कर्म-क्रिया-अन्वयाय</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch6_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch6_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — अन्वय-पूर्तिः</span>\n        <span class=\"word-limit-pill\">रिक्तस्थानपूर्तिः</span>\n      </div>\n      <div class=\"q-text\">श्लोकस्य अन्वयं पूरयत:<br><em>'उदये सविता रक्तो रक्तश्चास्तमये तथा। सम्पत्तौ च विपत्तौ च महतामेकरूपता॥'</em><br>अन्वयः: सविता उदये (१) _____ भवति, तथा च अस्तमये (२) _____ भवति। तथैव महताम् (३) _____ च विपत्तौ च (४) _____ भवति।</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>अन्वयः: सविता उदये <strong>(१) रक्तः</strong> भवति, तथा च अस्तमये <strong>(२) रक्तः</strong> भवति। तथैव महताम् <strong>(३) सम्पत्तौ</strong> च विपत्तौ च <strong>(४) एकरूपता</strong> भवति।</p>\n</div>\n<div class=\"hi-trans\">\n  <strong>भावार्थ:</strong> जैसे सूर्य उदय और अस्त दोनों समय एक समान लाल रहता है, वैसे ही महान पुरुष सुख और दुःख दोनों में सदैव समभाव और स्थिरचित्त रहते हैं।\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् रिक्तस्थाने</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch6_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch6_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — समास-विग्रहं कुरुत</span>\n        <span class=\"word-limit-pill\">विग्रहः अथवा समस्तपदम्</span>\n      </div>\n      <div class=\"q-text\">(क) उद्यमसम् = _____<br>(ख) शरीरस्थः = _____<br>(ग) निर्बलः = _____<br>(घ) देहविनाशाय = _____</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) उद्यमसम् = <strong>उद्यमेन समः</strong> (तृतीया तत्पुरुषः)</p>\n  <p>(ख) शरीरस्थः = <strong>शरीरे स्थितः</strong> (सप्तमी तत्पुरुषः)</p>\n  <p>(ग) निर्बलः = <strong>निर्गतं बलं यस्मात् सः</strong> (बहुव्रीहिः / अव्ययीभावः)</p>\n  <p>(घ) देहविनाशाय = <strong>देहस्य विनाशाय</strong> (षष्ठी तत्पुरुषः)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विग्रहस्य शुद्धनाम्ने च</span><span class=\"marking-marks\">१/२ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch6_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch6_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — विलोमपदानि लिखत</span>\n        <span class=\"word-limit-pill\">संस्कृत विलोमपदानि</span>\n      </div>\n      <div class=\"q-text\">पाठात् चित्वा विलोमपदानि लिखत:<br>(क) प्रसीदति × _____<br>(ख) मूर्खः × _____<br>(ग) बली × _____<br>(घ) सुलभम् × _____</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) प्रसीदति × <strong>प्रकुप्यति</strong></p>\n  <p>(ख) मूर्खः × <strong>पण्डितः / विद्वान्</strong></p>\n  <p>(ग) बली × <strong>निर्बलः</strong></p>\n  <p>(घ) सुलभम् × <strong>दुर्लभम्</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-विलोमपदलेखनाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #7c3aed;\">\n        <div class=\"cbq-type\" style=\"color:#7c3aed;\">चरित्रनिर्माण-दक्षता (NEP 2020 Character Building)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> 'आलस्यं हि मनुष्याणां शरीरस्थो महान् रिपुः' इति कथनेन छात्रजीवने कः प्रभावः दृश्यते? (शब्द-सीमा: ३०-४५ शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>विद्यार्थिजीवने आलस्यं सर्वप्रगतेः विनाशकं वर्तते। आलसी छात्रः ज्ञानं, सफलाङ्कान्, समयं च नाशयति। उद्यमेन (परिश्रमेन) विना विद्या न प्राप्यते। अतः छात्रैः आलस्यं परित्यज्य नित्यं कर्मशीलेन भवितव्यम्।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(5)\">← पूर्वतनः पाठः (Ch 5)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\">अग्रिमः पाठः (Ch 7) →</button>\n  </div>\n</section>","7":"<section class=\"chapter-section\" id=\"ch7\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ७</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">नाटकम् (संवादः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>सप्तमः पाठः — सौहार्दं प्रकृतेः शोभा</h2>\n      <p class=\"ch-author\">पर्यावरणपरक-संवादनाटकम्</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>वनपशूनां मध्ये वनराजपदप्राप्तये परस्परकलहः, मयूर-सिंह-काक-पिक-वानराणां संवादः तथा च प्रकृतिमातुः उपदेशः यत् सर्वेषां प्राणिनां परस्परसद्भावः एव प्रकृतेः वास्तविकं सौन्दर्यम्।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch7_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch7_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) कः आत्मानं वनराजः मन्यते?<br>(ख) काकस्य वर्णः कीदृशः भवति?<br>(ग) पिक-काकयोः भेदः कदा ज्ञायते?<br>(घ) कः सर्वेषां प्राणिनां रक्षायै उपायं चिन्तयितुं वदति?<br>(ङ) अन्ततः प्रकृतिमाता किमुपदिशति?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">सिंहः</span></p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">कृष्णः</span> (कालः)</p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">वसन्तसमये</span></p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">बकः</span> (बगुला)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">परस्परं मिलित्वा मोदध्वम्</span> (स्नेहेन जीवनं यापयत)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदाय शुद्धविभक्तियुक्ताय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch7_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch7_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) अन्ते सर्वे पशवः मिलित्वा कस्य राज्याभिषेकाय सज्जाः भवन्ति?<br>(ख) मयूरः कथं नृत्यमुद्रायां स्थितः भवति?<br>(ग) बकः मीनान् कथं भक्षयति?<br>(घ) काकः स्वप्रशंसां कुर्वन् किं कथयति?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> अन्ते सर्वे पशवः मिलित्वा उलूकस्य (उल्लूकस्य) राज्याभिषेकाय सज्जाः भवन्ति।</p>\n  <p><strong>(ख)</strong> मयूरः स्वपिच्छान् उद्घाट्य (पक्षान् प्रसार्य) नृत्यमुद्रायां स्थितः भवति।</p>\n  <p><strong>(ग)</strong> बकः शीतले जले अविचलः ध्यानमग्नः स्थित्वा वराकान् मीनान् छलेन अधिगृह्य क्रूरताया भक्षयति।</p>\n  <p><strong>(घ)</strong> काकः कथयति यत् 'अहं सत्यप्रियः अस्मि, विद्यार्थिनः कृते काकचेष्टा आदर्शभूता भवति, मम च एकता जगत्प्रसिद्धा अस्ति'।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वाक्यविन्यासाय कर्तृ-क्रिया-सङ्गतये च</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch7_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch7_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — कः कं प्रति कथयति?</span>\n        <span class=\"word-limit-pill\">वक्ता श्रोता च</span>\n      </div>\n      <div class=\"q-text\">अधोलिखितवाक्येषु कः कं प्रति कथयति?<br>(क) 'क्रोधाविष्टः सिंहः इतस्ततः धावति गर्जति च।'<br>(ख) 'रे धूर्त! किमहं न वनराजः?'<br>(ग) 'अलमलमतिविकत्थनेन। किमर्थं वृथा कलहं कुरुथ?'<br>(घ) 'सर्वथा सम्यगुक्तं सिंहभ्रात्रा।'</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> वक्ता: <strong>वानराः</strong> | श्रोता: <strong>सिंहं प्रति</strong></p>\n  <p><strong>(ख)</strong> वक्ता: <strong>सिंहः</strong> | श्रोता: <strong>वानरान् प्रति</strong></p>\n  <p><strong>(ग)</strong> वक्ता: <strong>प्रकृतिमाता</strong> | श्रोता: <strong>सर्वान् पशून् प्रति</strong></p>\n  <p><strong>(घ)</strong> वक्ता: <strong>वानरः / काकः</strong> | श्रोता: <strong>सिंहं प्रति</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वक्तुः श्रोतुश्च यथार्थनाम्ने</span><span class=\"marking-marks\">१ अंकः प्रतिवाक्यम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch7_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch7_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नचिह्नयुक्त पूर्णवाक्यम्</span>\n      </div>\n      <div class=\"q-text\">(क) सिंहः <u>वानराभ्याम्</u> प्रताडितः।<br>(ख) मयूरस्य नृत्यं <u>प्रकृतेः</u> आराधना।<br>(ग) सर्वे <u>प्रकृतिमातरम्</u> प्रणमन्ति।<br>(घ) बकः <u>मीनान्</u> क्रूरताया भक्षयति।</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> सिंहः <strong>काभ्याम्</strong> प्रताडितः?</p>\n  <p><strong>(ख)</strong> मयूरस्य नृत्यं <strong>कस्याः</strong> आराधना?</p>\n  <p><strong>(ग)</strong> सर्वे <strong>काम्</strong> प्रणमन्ति?</p>\n  <p><strong>(घ)</strong> बकः <strong>कान्</strong> क्रूरताया भक्षयति?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-प्रश्नवाचकपदाय + (?) चिह्नम्</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch7_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch7_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — मञ्जूषातः समुचितपदं चित्वा रिक्तस्थानपूर्तिः</span>\n        <span class=\"word-limit-pill\">उचितपदचयनम्</span>\n      </div>\n      <div class=\"q-text\">[मञ्जूषा: आत्मप्रशंसारहितः, पिकः, मयूरः, अविचलः]<br>(१) काकः कृष्णः _____ कृष्णः।<br>(२) _____ अहिभुक् अपि कथ्यते।<br>(३) बकः जले _____ तिष्ठति।<br>(४) उलूकः _____ निर्लिप्तश्चासीत्।</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(१) काकः कृष्णः <strong>पिकः</strong> कृष्णः।</p>\n  <p>(२) <strong>मयूरः</strong> अहिभुक् अपि कथ्यते।</p>\n  <p>(३) बकः जले <strong>अविचलः</strong> तिष्ठति।</p>\n  <p>(४) उलूकः <strong>आत्मप्रशंसारहितः</strong> निर्लिप्तश्चासीत्।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिरिक्तस्थानं शुद्धपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #059669;\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">पर्यावरण-पारस्परिक-निर्भरता (Ecosystem Balance)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> 'सौहार्दं प्रकृतेः शोभा' इति पाठस्य मुख्यः पर्यावरण-सन्देशः कः अस्ति? (शब्द-सीमा: ३०-४५ शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>अनेन पाठेन ज्ञायते यत् प्रकृतौ कोऽपि जीवः लघुः वा महान् नास्ति। सिंहः, मयूरः, काकः, वृक्षाः च सर्वे परस्परं संबद्धाः सन्ति। यदि वयं परस्परं कलहं कृत्वा प्रकृतेः नाशं करिष्यामः, तर्हि सर्वेषामेव अस्तित्वं विनङ्क्ष्यति। अतः सहअस्तित्वं (Co-existence) एव प्रकृतेः शोभा अस्ति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(6)\">← पूर्वतनः पाठः (Ch 6)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\">अग्रिमः पाठः (Ch 8) →</button>\n  </div>\n</section>","8":"<section class=\"chapter-section\" id=\"ch8\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ८</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">गद्यभागः (कथा) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>अष्टमः पाठः — विचित्रः साक्षी</h2>\n      <p class=\"ch-author\">रचयिता: श्री ओंप्रकाश ठाकुरः (बङ्किमचन्द्रस्य सत्यकथाधारितः)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>न्यायाधीशस्य बङ्किमचन्द्रस्य सूक्ष्मबुद्ध्या निरपराधिनः निर्धनस्य मुक्तिः तथा च चौरस्य आरक्षिणः दण्डविधानम्। शवेन साक्ष्यदानस्य अद्भुता युक्तिः।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch8_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch8_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) कस्य विवशता आसीत्?<br>(ख) विचित्रा का?<br>(ग) रात्रौ कुत्र निवासः अकर्तव्यः?<br>(घ) वस्तुतः चौरः कः आसीत्?<br>(ङ) निष्पक्षन्यायं कः प्रदत्तवान्?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">निर्धनजनस्य</span></p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">दैवगतिः</span></p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">विजने प्रदेशे</span> (एकान्ते)</p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">ग्रामस्य आरक्षी</span> (रक्षकः)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">न्यायाधीशः बङ्किमचन्द्रः</span></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch8_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch8_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) निर्धनः जनः कथमर्थोपार्जनं कृतवान्?<br>(ख) जनः किमर्थं पदातिः गच्छति स्म?<br>(ग) चौरः कं निशम्य बहिः पलायितः?<br>(घ) न्यायाधीशः कस्मै कारागारदण्डम् आदिशत्?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> निर्धनः जनः भूरि (अत्यधिकं) परिश्रमं कृत्वा किञ्चिद् वित्तम् (धनम्) उपार्जितवान्।</p>\n  <p><strong>(ख)</strong> अर्थकार्श्येन (धनस्य अभावेन) पीडितः स जनः बसयानं विहाय पदातिरेव (पादचारेण) प्राचलत्।</p>\n  <p><strong>(ग)</strong> चौरः प्रबुद्धस्य अतिथेः पादध्वनिं निशम्य बहिः पलायितुम् ऐच्छत्।</p>\n  <p><strong>(घ)</strong> न्यायाधीशः चौरकृत्यापराधिनम् आरक्षिणं कारागारदण्डम् आदिशत्, अतिथिं च ससम्मानं मुक्तवान्।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्यविन्यासाय तथ्यशुद्धये च</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch8_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch8_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नचिह्नयुक्त पूर्णवाक्यम्</span>\n      </div>\n      <div class=\"q-text\">प्रश्ननिर्माणं कुरुत:<br>(क) स <u>पदातिरेव</u> प्राचलत्।<br>(ख) <u>चौरस्य</u> पादध्वनिना अतिथिः प्रबुद्धः।<br>(ग) न्यायाधीशः <u>बङ्किमचन्द्रः</u> आसीत्।<br>(घ) स भारवेदनया <u>क्रन्दति स्म</u>।</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> स <strong>कथम्</strong> प्राचलत्?</p>\n  <p><strong>(ख)</strong> <strong>कस्य</strong> पादध्वनिना अतिथिः प्रबुद्धः?</p>\n  <p><strong>(ग)</strong> न्यायाधीशः <strong>कः</strong> आसीत्?</p>\n  <p><strong>(घ)</strong> स कया <strong>अक्रन्दत् / किं करोति स्म</strong>?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-प्रश्नवाचकपदम् + (?) चिह्नम्</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch8_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch8_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — घटनाक्रमानुसारेण लेखनम्</span>\n        <span class=\"word-limit-pill\">कथाक्रमानुसारं वाक्यानि</span>\n      </div>\n      <div class=\"q-text\">घटनाक्रमानुसारेण वाक्यानि लिखत:<br>१. चौरः एव आरक्षी आसीत्।<br>२. कश्चन निर्धनः जनः वित्तम् उपार्जितवान्।<br>३. रात्रौ स कस्यचित् गृहस्थस्य गृहे वासम् अकरोत्।<br>४. शवः प्रावारकम् अपसार्य न्यायाधीशाया निवेदितवान्।<br>५. न्यायाधीशेन आरक्षी कारागारे निक्षिप्तः।<br>६. आरक्षी अतिथिं चौर्याभियोगे कारागारे अप्रक्षिपत्।<br>७. उभौ शवम् आनीय चत्वरे स्थापितवन्तौ।<br>८. न्यायाधीशः पुनः विचारार्थम् आदिष्टवान्।</div>\n      <div class=\"q-marks\">४ अंकाः (१/२ × ८)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>यथार्थः क्रमः:</strong></p>\n  <ol style=\"margin-left:20px; line-height:1.8;\">\n    <li>(२) कश्चन निर्धनः जनः वित्तम् उपार्जितवान्।</li>\n    <li>(३) रात्रौ स कस्यचित् गृहस्थस्य गृहे वासम् अकरोत्।</li>\n    <li>(१) चौरः एव ग्रामस्य आरक्षी आसीत्।</li>\n    <li>(६) आरक्षी अतिथिं चौर्याभियोगे कारागारे अप्रक्षिपत्।</li>\n    <li>(८) न्यायाधीशः पुनः विचारार्थम् आदिष्टवान्।</li>\n    <li>(७) उभौ शवम् आनीय चत्वरे स्थापितवन्तौ।</li>\n    <li>(४) शवः प्रावारकम् अपसार्य न्यायाधीशाया निवेदितवान्।</li>\n    <li>(५) न्यायाधीशेन आरक्षी कारागारे निक्षिप्तः अतिथिः च मुक्तः।</li>\n  </ol>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रमबद्ध-वाक्यरचनायै</span><span class=\"marking-marks\">१/२ अंकः प्रतिवाक्यम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch8_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch8_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — सन्धि-सन्धिविच्छेदं कुरुत</span>\n        <span class=\"word-limit-pill\">शुद्धसन्धिकार्यम्</span>\n      </div>\n      <div class=\"q-text\">(क) पदातिरेव = _____ + _____<br>(ख) निशम्य = _____ + _____ + _____<br>(ग) तत्रैव = _____ + _____<br>(घ) इत्याकर्ण्य = _____ + _____</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) पदातिरेव = <strong>पदातिः + एव</strong></p>\n  <p>(ख) निशम्य = <strong>नि + शम् + ल्यप्</strong></p>\n  <p>(ग) तत्रैव = <strong>तत्र + एव</strong></p>\n  <p>(घ) इत्याकर्ण्य = <strong>इति + आकर्ण्य</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिपदं शुद्धसन्धये</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #d97706;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">न्यायप्रणाली-विश्लेषणम् (NEP 2020 Critical Thinking)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> न्यायाधीशेन बङ्किमचन्द्रेण सत्यस्य अनुसन्धानाय या युक्तिः प्रयुक्ता, सा तस्य कीदृशं चातुर्यं प्रकटयति? (शब्द-सीमा: ३०-४५ शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>न्यायाधीशः जानाति स्म यत् निर्धनः अतिथिः निर्दोषः अस्ति किन्तु प्रमाणाभावात् निर्णयः कठिनः आसीत्। अतः तेन शवस्य साक्ष्यकल्पना कृत्वा मनोवैज्ञानिकरीत्या आरक्षिणः मुखात् एव सत्यम् उद्घाटितम्। एषा युक्तिः तस्य अगाधं मेधाशक्तित्वं न्यायप्रियतां च प्रदर्शयति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(7)\">← पूर्वतनः पाठः (Ch 7)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\">अग्रिमः पाठः (Ch 9) →</button>\n  </div>\n</section>","9":"<section class=\"chapter-section\" id=\"ch9\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ९</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">पद्यभागः (सूक्तयः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>नवमः पाठः — सूक्तयः</h2>\n      <p class=\"ch-author\">मूलग्रन्थः: तमिल-वेदः 'तिरुक्कुरल्' (संस्कृतानुवादः)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>सत्यभाषणम्, पितृऋणम्, विद्वत्ता, समत्वम्, सदाचारः च। तिरुक्कुरलग्रन्थस्य नीतिसूक्तयः जीवनस्य वास्तविकं मार्गं दर्शयन्ति।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch9_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch9_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) पिता पुत्राय बाल्ये किं यच्छति?<br>(ख) मूढधीः कीदृशीं वाचं परित्यजति?<br>(ग) संसारे के चक्षुष्मन्तः प्रकीर्तिताः?<br>(घ) प्राणैः अपि कः रक्षणीयः?<br>(ङ) आत्मनः श्रेयः इच्छन् नरः कीदृशं कर्म न कुर्यात्?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">विद्याधनम्</span> (महत् विद्याधनम्)</p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">धर्मप्रदाम्</span> (मधुरां धर्मयुक्ताम्)</p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">विद्वांसः</span></p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">सदाचारः</span> (आचारः)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">अहितम्</span> (पापकर्म)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch9_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch9_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) कस्य चित्ते वाचि च सरलता भवति चेत् सा का कथ्यते?<br>(ख) वाक्पटुः धैर्यवान् मन्त्री कैः न परिभूयते?<br>(ग) लोके विद्वांसः एव के सन्ति?<br>(घ) धर्मप्रदां वाचं त्यक्त्वा मूढधीः किं खादति?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> यस्य चित्ते (मनसि) वाचि (वाण्याम्) च सरलता भवति, तदेव वस्तुतः 'ऋजुता' वा 'समत्वम्' इति कथ्यते।</p>\n  <p><strong>(ख)</strong> वाक्पटुः, धैर्यवान्, सभायामकातरः मन्त्री परैः (शत्रुभिः) केनापि प्रकारेण न परिभूयते।</p>\n  <p><strong>(ग)</strong> लोके विद्वांसः एव वास्तविकरूपेण चक्षुष्मन्तः (नेत्रवन्तः) सन्ति, इतरेषां वदने चक्षूंषि तु केवलं नाममात्रेण वर्तेते।</p>\n  <p><strong>(घ)</strong> धर्मप्रदां वाचं त्यक्त्वा यः परुषां (कठोराम्) वाचं वदति, स पक्वं फलं विहाय अपक्वं (कच्चा) फलं खादति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्ये शुद्ध-अन्वयाय</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch9_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch9_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — श्लोकस्य अन्वयं पूरयत</span>\n        <span class=\"word-limit-pill\">रिक्तस्थानपूर्तिः</span>\n      </div>\n      <div class=\"q-text\"><em>'पिता यच्छति पुत्राय बाल्ये विद्याधनं महत्। पितास्य किं तपो तेपे इत्युक्तिस्तत्कृतज्ञता॥'</em><br>अन्वयः: पिता पुत्राय बाल्ये महत् (१) _____ यच्छति। अस्य पिता किं (२) _____ तेपे इति (३) _____ तत् (४) _____ अस्ति।</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>अन्वयः: पिता पुत्राय बाल्ये महत् <strong>(१) विद्याधनं</strong> यच्छति। अस्य पिता किं <strong>(२) तपः</strong> तेपे इति <strong>(३) उक्तिः</strong> तत् <strong>(४) कृतज्ञता</strong> अस्ति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिरिक्तस्थानं शुद्धपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch9_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch9_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — समानार्थकपदानि लिखत</span>\n        <span class=\"word-limit-pill\">संस्कृत पदानि</span>\n      </div>\n      <div class=\"q-text\">(क) प्रभुतम = _____<br>(ख) श्रेयः = _____<br>(ग) चित्तम् = _____<br>(घ) सभा = _____</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) प्रभुतम् = <strong>भूरि / अत्यधिकम्</strong></p>\n  <p>(ख) श्रेयः = <strong>कल्याणम् / शुभम्</strong></p>\n  <p>(ग) चित्तम् = <strong>मनः / हृदयम्</strong></p>\n  <p>(घ) सभा = <strong>संसद् / मण्डली</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-पर्यायपदाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #7c3aed;\">\n        <div class=\"cbq-type\" style=\"color:#7c3aed;\">वाणी-माधुर्यम् एवं सदाचारः (Communication Ethics)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> 'वाक्पटुता' इति गुणस्य छात्रजीवने नेतृत्वविकासे च किं स्थानं वर्तते? (शब्द-सीमा: ३०-४५ शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>यः जनः सभायां निर्भयः, वाक्पटुः, मधुरभाषी च भवति, स सर्वत्र आदरं प्राप्नोति। वाणी एव मनुष्यस्य वास्तविकं भूषणम् अस्ति। छात्रजीवने मधुरया सन्तुलितया च वाण्या मित्राणि, गुरवः, समाजश्च प्रसीदन्ति, येन नेतृत्वगुणानां विकासः भवति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(8)\">← पूर्वतनः पाठः (Ch 8)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\">अग्रिमः पाठः (Ch 10) →</button>\n  </div>\n</section>","10":"<section class=\"chapter-section\" id=\"ch10\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः १०</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">गद्यभागः (निबन्धः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>दशमः पाठः — भूकम्पविभीषिका</h2>\n      <p class=\"ch-author\">आपत्कालीन-वैज्ञानिक-निबन्धः</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>२००१ तमे ख्रीष्टाब्दे गुजरातराज्ये संजातस्य भीषणभूकम्पस्य विभीषिका, भूकम्पस्य वैज्ञानिकानां मते कारणानि तथा च पर्यावरणसन्तुलनरक्षायाः आह्वानम्।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch10_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch10_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) कस्य विभीषिका कच्छजनपदं ध्वंसावशेषेषु परिवर्तितवती?<br>(ख) कीदृशानि भवनानि क्षणमात्रेण धराशायीनि अभवन्?<br>(ग) गुजरातभूकम्पः कस्मिन् वर्षे अभवत्?<br>(घ) भूकम्पस्य केन्द्रबिन्दुः कः जनपदः आसीत्?<br>(ङ) पृथिव्याः अन्तर्गर्भे केषां सङ्घर्षणात् कम्पनं जायते?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">भूकम्पस्य</span></p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">बहुभूमिकानि</span> (बहुमञ्जिला भवनानि)</p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">२००१ तमे वर्षे</span> (२६ जनवरी २००१)</p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">कच्छजनपदः</span></p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">शिलाखण्डानाम् / प्लेट्स-इत्याख्यानाम्</span></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदोत्तराय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch10_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch10_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) भूकम्पेन कच्छप्रदेशस्य का स्थितिः जाता?<br>(ख) महाविनाशस्य काले जनाः किं कुर्वन्ति स्म?<br>(ग) वैज्ञानिकाः भूकम्पस्य कारणं किं मन्यन्ते?<br>(घ) प्रकृतेः सन्तुलनं कथं रक्षितव्यम्?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> भूकम्पेन समग्रः कच्छप्रदेशः, विशालाः प्रासादाः, सेतवः च क्षणेनैव मृत्तिकाक्रीडनकम् इव खण्ड-खण्डं भूत्वा ध्वंसावशेषेषु परिणताः।</p>\n  <p><strong>(ख)</strong> महाविनाशकाले विवशाः जनाः हाहाकारं कुर्वन्तः क्रन्दन्तः च इतस्ततः अशरणतया अधावन्।</p>\n  <p><strong>(ग)</strong> वैज्ञानिकाः मन्यन्ते यत् पृथिव्याः अन्तर्गर्भे विद्यमानानां बृहत्पाषाणशिलानां सङ्घर्षणात् विदारणात् च कम्पनं जायते येन भूकम्पः उत्पद्यते।</p>\n  <p><strong>(घ)</strong> वृक्षाणां रोपणेन, पर्वतानां सुरक्षया, खननानां नियन्त्रणेन तथा च नदीनां प्रवाहे अनुचितहस्तक्षेपत्यागेन प्रकृतेः सन्तुलनं रक्षितव्यम्।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-पूर्णवाक्यरचनायै</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch10_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch10_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — प्रकृति-प्रत्यय-विभागं कुरुत</span>\n        <span class=\"word-limit-pill\">धातु-प्रत्यय-विभागः</span>\n      </div>\n      <div class=\"q-text\">(क) विदार्य = _____ + _____ + _____<br>(ख) कम्पनम् = _____ + _____<br>(ग) पतितः = _____ + _____<br>(घ) संजातम् = _____ + _____ + _____</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) विदार्य = <strong>वि + दृ + ल्यप्</strong></p>\n  <p>(ख) कम्पनम् = <strong>कम्प् + ल्युट्</strong></p>\n  <p>(ग) पतितः = <strong>पत् + क्त</strong></p>\n  <p>(घ) संजातम् = <strong>सम् + जन् + क्त</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-धातुप्रत्ययविभागाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch10_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch10_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नवाचक-वाक्यम्</span>\n      </div>\n      <div class=\"q-text\">(क) <u>कच्छप्रदेशः</u> ध्वंसावशेषेषु परिवर्तितः।<br>(ख) <u>वैज्ञानिकाः</u> कम्पनस्य कारणं वदन्ति।<br>(ग) सः <u>२००१ तमे वर्षे</u> अभवत्।<br>(घ) <u>शिलाखण्डानाम्</u> सङ्घर्षणात् कम्पनं भवति।</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <strong>कः</strong> ध्वंसावशेषेषु परिवर्तितः?</p>\n  <p><strong>(ख)</strong> <strong>के</strong> कम्पनस्य कारणं वदन्ति?</p>\n  <p><strong>(ग)</strong> सः <strong>कदा / कस्मिन् वर्षे</strong> अभवत्?</p>\n  <p><strong>(घ)</strong> <strong>केषाम्</strong> सङ्घर्षणात् कम्पनं भवति?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-प्रश्नवाचकपदम् + (?)</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #dc2626;\">\n        <div class=\"cbq-type\" style=\"color:#dc2626;\">आपत्प्रबन्धन-जागरूकता (Disaster Management & Preparedness)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> भूकम्पापत्तिसमये छात्रैः नागरिकाणां च कृते कानि प्राथमिकसुरक्षोपायनिर्देशानि पालनीयानि? (शब्द-सीमा: ३५-५० शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>भूकम्पकाले भयभीताः न भवितव्यम्। यदि गृहे स्युः तर्हि दृढमेजायाः अधः स्थातव्यम्, विद्युत्प्रवाहः स्थगयितव्यः, बहुभूमिकभवनेभ्यः दूरं गत्वा उद्घाटे प्राङ्गणे वा क्षेत्रे एकत्रिताः भवितव्यम्। लिफ्ट-इत्यस्य प्रयोगः कदापि न विधेयः।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(9)\">← पूर्वतनः पाठः (Ch 9)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\">अग्रिमः पाठः (Ch 11) →</button>\n  </div>\n</section>","11":"<section class=\"chapter-section\" id=\"ch11\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ११</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">नाटकम् (संवादः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>एकादशः पाठः — प्राणेभ्योऽपि प्रियः सुहृद्</h2>\n      <p class=\"ch-author\">मूलनाटकम्: मुद्राराक्षसम् (रचयिता: महाकवि-विशाखदत्तः)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>चाणक्य-चन्दनदासयोः प्रसिद्धः संवादः। चन्दनदासः राजकोपादपि न बिभेति, स्वप्राणान् पणीकृत्य स्वमित्रस्य अमात्यराक्षसस्य कुटुम्बस्य रक्षणं करोति।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch11_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch11_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) चन्दनदासः कस्य गृहजनं स्वगृहे रक्षितवान्?<br>(ख) चाणक्यः कं द्रष्टुम् इच्छति?<br>(ग) चन्दनदासस्य व्यवसायः कः आसीत्?<br>(घ) प्राणेभ्योऽपि प्रियः कः भवति?<br>(ङ) कस्य दण्डभयं चाणक्यः दर्शयति?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">अमात्यराक्षसस्य</span></p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">चन्दनदासम्</span> (श्रेष्ठिनम्)</p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">मणिकारश्रेष्ठिता / व्यापारः</span></p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">सुहृद्</span> (मित्रम्)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">नृपस्य / राज्ञः चन्द्रगुप्तस्य</span></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch11_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch11_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) चन्दनदासः चाणक्यं प्रति किं प्रतिज्ञां करोति?<br>(ख) चाणक्यः चन्दनदासस्य कीदृशं गुणं प्रशंसति?<br>(ग) चन्दनदासस्य आचरणं किमर्थं राजविरुद्धम् आसीत्?<br>(घ) अन्ते चाणक्यः चन्दनदासं दृष्ट्वा मनसि किं विचिन्तयति?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> चन्दनदासः दृढतया अवदत् यत् 'यदि मम प्राणाः अपि गच्छेयुः, तथापि अहम् आश्रितस्य मित्रस्य गृहजनं न समर्पयिष्यामि'।</p>\n  <p><strong>(ख)</strong> चाणक्यः चन्दनदासस्य अप्रतिमाम् आत्मत्यागनिष्ठां, मित्रप्रेम तथा च निर्भयतां प्रशंसति।</p>\n  <p><strong>(ग)</strong> राजद्रोहिणः अमात्यराक्षसस्य कलत्रं (कुटुम्बम्) स्वगृहे गोपायित्वा चन्दनदासस्य आचरणं राजशासनविरुद्धम् आसीत्।</p>\n  <p><strong>(घ)</strong> चाणक्यः मनसि विचिन्तयति यत् 'अहो दुष्करं कुर्यादिदानीं शिबिना विना' अर्थात् चन्दनदासस्य सदृशः त्यागवीरः कलियुगे दुर्लभः अस्ति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्ये शुद्ध-वाक्यविन्यासाय</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch11_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch11_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — कः कं प्रति कथयति?</span>\n        <span class=\"word-limit-pill\">वक्ता श्रोता च</span>\n      </div>\n      <div class=\"q-text\">(क) 'तात! किं ममापराधेन राज्ञः कोपः?'<br>(ख) 'भो श्रेष्ठिन्! प्रीताभ्यः प्रकृतिभ्यः राजानः प्रतिप्रियमिच्छन्ति।'<br>(ग) 'इदं मे दृढतरं निश्चयः यत् न समर्पयामि गृहजनम्।'</div>\n      <div class=\"q-marks\">१ × ३ = ३ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> वक्ता: <strong>चन्दनदासः</strong> | श्रोता: <strong>चाणक्यं प्रति</strong></p>\n  <p><strong>(ख)</strong> वक्ता: <strong>चाणक्यः</strong> | श्रोता: <strong>चन्दनदासं प्रति</strong></p>\n  <p><strong>(ग)</strong> वक्ता: <strong>चन्दनदासः</strong> | श्रोता: <strong>चाणक्यं प्रति</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वक्तुः श्रोतुश्च शुद्धनाम्ने</span><span class=\"marking-marks\">१ अंकः प्रतिवाक्यम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch11_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch11_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — विलोमपदानि लिखत</span>\n        <span class=\"word-limit-pill\">संस्कृत पदानि</span>\n      </div>\n      <div class=\"q-text\">(क) प्रियः × _____<br>(ख) दोषः × _____<br>(ग) सुहृद् × _____<br>(घ) प्रीताभ्यः × _____</div>\n      <div class=\"q-marks\">२ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>(क) प्रियः × <strong>अप्रियः</strong></p>\n  <p>(ख) दोषः × <strong>गुणः</strong></p>\n  <p>(ग) सुहृद् × <strong>रिपुः / शत्रुः</strong></p>\n  <p>(घ) प्रीताभ्यः × <strong>अकुपिताभ्यः / भीताभ्यः</strong></p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-विलोमपदलेखनाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #2563eb;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">मित्रता एवं निष्ठा (Loyalty & Friendship Values)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> चन्दनदासस्य चरित्रेण वर्तमानयुगस्य नागरिकाणां कृते कः आदर्शः प्रस्तूयते? (शब्द-सीमा: ३०-४५ शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>वर्तमानयुगे स्वार्थपरायणतायाः बाहुल्ये चन्दनदासस्य चरित्रं निष्ठायाः सर्वोच्चं प्रतीकम् अस्ति। सः धनलोभात् मृत्युभयाच्च विचलितः न अभवत्। मित्रस्य संकटकाले प्राणान् अर्पयितुं यः तत्परः भवति, स एव सच्चा सुहृद् भवति।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(10)\">← पूर्वतनः पाठः (Ch 10)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\">अग्रिमः पाठः (Ch 12) →</button>\n  </div>\n</section>","12":"<section class=\"chapter-section\" id=\"ch12\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः १२</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">पद्यभागः (अन्योक्तयः) • शेमुषी भाग - २ (Code 122)</div>\n      <h2>द्वादशः पाठः — अन्योक्तयः</h2>\n      <p class=\"ch-author\">रचयिता: पण्डितराज-जगन्नाथः (भामिनीविलासः)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>प्रतीकानां (हंसः, सरः, चातकः, कोकिलः, सुवर्णः) माध्यमेन मानवेभ्यः आत्मसम्मानस्य, स्वाभिमानस्य, गुणग्राहकतायाः च अप्रत्यक्षः उपदेशः।</p>\n    </div>\n  </div>\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (CBSE Marking Scheme & Word Limits 2026-27)</div>\n\n  <div class=\"q-card\" id=\"c10sk_ch12_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch12_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः</span>\n      </div>\n      <div class=\"q-text\">एकपदेन उत्तरत:<br>(क) राजहंसेन कस्य शोभा भवति?<br>(ख) केन विना सरसः संकोचः न शोभते?<br>(ग) चातकः कुत्र वसति?<br>(घ) केषां वृष्टिभिः धरणी तृप्यति?<br>(ङ) सुवर्णस्य मुख्यं दुःखं किम्?</div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <span class=\"ans-highlight\">सरसः</span> (सरोवरस्य)</p>\n  <p><strong>(ख)</strong> <span class=\"ans-highlight\">बकेन</span></p>\n  <p><strong>(ग)</strong> <span class=\"ans-highlight\">वने</span></p>\n  <p><strong>(घ)</strong> <span class=\"ans-highlight\">वारिदानाम्</span> (मेघानाम्)</p>\n  <p><strong>(ङ)</strong> <span class=\"ans-highlight\">गुञ्जया सह तोलनम्</span> (रत्तिकाभिः सह तोलनम्)</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-एकपदाय</span><span class=\"marking-marks\">१/२ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch12_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch12_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः</span>\n      </div>\n      <div class=\"q-text\">पूर्णवाक्येन उत्तरत:<br>(क) सरसः वास्तविकः बन्धुः कः अस्ति?<br>(ख) चातकः किमर्थं मानी कथ्यते?<br>(ग) सुवर्णः केन कारणेन अत्यन्तं दुःखितः भवति?<br>(घ) भ्रमरः यदा सरोवरे पद्मानि संकुचन्ति तदा कुत्र गच्छति?</div>\n      <div class=\"q-marks\">१.५ × ४ = ६ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> सरसः वास्तविकः बन्धुः राजहंसः अस्ति यः आपत्काले सरसः संकोचे अपि तं न परित्यजति।</p>\n  <p><strong>(ख)</strong> चातकः पिपासाकुलोऽपि मृत्यं स्वीकरोति अथवा केवलं मेघं (इन्द्रम्) याचते, न तु अधमजनम्, अतः स मानी कथ्यते।</p>\n  <p><strong>(ग)</strong> सुवर्णः अग्नौ ताडनात् दाहनात् वा न दुःखितः भवति, किन्तु यदा अज्ञाः जनाः तं तुच्छया गुञ्जया (रक्तिकया) तोलयन्ति, तदा स परमं क्लिश्यति।</p>\n  <p><strong>(घ)</strong> यदा सरोवरे संकोचः भवति तदा भ्रमरः रसालमुकुलानि (आम्रमञ्जरीः) आश्रयितुं काननं गच्छति।</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्णवाक्ये शुद्ध-भावप्रतिपादनाय</span><span class=\"marking-marks\">१.५ अंकाः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch12_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch12_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — श्लोकान्वयः एवं भावार्थः</span>\n        <span class=\"word-limit-pill\">अन्वयपूर्तिः</span>\n      </div>\n      <div class=\"q-text\"><em>'रे रे चातक! सावधानमनसा मित्र क्षणं श्रूयताम्। अम्भोदा बहवो हि सन्ति गगने सर्वेऽपि नैतादृशाः॥'</em><br>अन्वयं पूरयत:<br>रे रे मित्र चातक! (१) _____ मनसा क्षणं श्रूयताम्। गगने बहवः (२) _____ सन्ति, किन्तु सर्वे अपि (३) _____ न सन्ति। अतः यं यं पश्यसि तस्य तस्य पुरतः दीनं वचः मा (४) _____।</div>\n      <div class=\"q-marks\">२.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p>अन्वयः: रे रे मित्र चातक! <strong>(१) सावधान-</strong> मनसा क्षणं श्रूयताम्। गगने बहवः <strong>(२) अम्भोदाः (मेघाः)</strong> सन्ति, किन्तु सर्वे अपि <strong>(३) एतादृशाः (वृष्टिकारकाः)</strong> न सन्ति। अतः यं यं पश्यसि तस्य तस्य पुरतः दीनं वचः मा <strong>(४) ब्रूहि</strong>।</p>\n</div>\n<div class=\"hi-trans\">\n  <strong>भावार्थ:</strong> हे स्वाभिमानी मनुष्य! आकाश में तो बहुत से बादल गरजते हैं, पर सब बरसते नहीं। इसलिए प्रत्येक व्यक्ति के सामने गिड़गिड़ाकर अपनी दीनता प्रकट मत करो, केवल योग्य और दानी व्यक्ति से ही याचना करो।\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिरिक्तस्थानं शुद्धपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भावार्थ-स्पष्टतायै</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"c10sk_ch12_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c10sk_ch12_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नवाचक-वाक्यम्</span>\n      </div>\n      <div class=\"q-text\">(क) <u>राजहंसेन</u> सरसः शोभा भवति।<br>(ख) चातकः <u>वने</u> वसति।<br>(ग) जनाः सुवर्णं <u>गुञ्जया</u> तोलयन्ति।<br>(घ) <u>वारिदाः</u> गगने गर्जन्ति।</div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n<div class=\"sans-ans-block\">\n  <p><strong>(क)</strong> <strong>केन</strong> सरसः शोभा भवति?</p>\n  <p><strong>(ख)</strong> चातकः <strong>कुत्र</strong> वसति?</p>\n  <p><strong>(ग)</strong> जनाः सुवर्णं <strong>कया</strong> तोलयन्ति?</p>\n  <p><strong>(घ)</strong> <strong>के</strong> गगने गर्जन्ति?</p>\n</div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध-प्रश्नवाचकपदम् + (?)</span><span class=\"marking-marks\">१ अंकः प्रतिपदम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #d97706;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">स्वाभिमान-गुणग्राहकता (Self-Respect & Merit Appreciation)</div>\n        <div class=\"cbq-question\"><strong>प्रश्नः:</strong> सुवर्णस्य व्यथया पण्डितराज-जगन्नाथेन गुणिजनानां का व्यथा समाजे वर्णिता अस्ति? (शब्द-सीमा: ३५-५० शब्दाः)</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\"><p>यथा सुवर्णः अग्नौ तपनात् न दुःखितः किन्तु गुञ्जया सह तोलनेन अपमानितः भवति, तथैव समाजे विद्वान् गुणवान् जनः दारिद्र्यात् न दुःखितः भवति। किन्तु यदा मूर्खाः अविवेकिनः वा शासकाः तस्य तुलनां हीनचरित्रैः सह कुर्वन्ति, तदा स मर्मान्तिकां वेदनाम् अनुभवति। गुणीजनस्य सम्मानं सर्वोपरि भवेत्।</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(11)\">← पूर्वतनः पाठः (Ch 11)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <div></div>\n  </div>\n</section>"};
